def gini(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    counts = {}
    for lab in labels:
        counts[lab] = counts.get(lab, 0) + 1
    return 1.0 - sum((c / n) ** 2 for c in counts.values())

def best_split(xs, labels):
    def _gini(labs):
        n = len(labs)
        if n == 0:
            return 0.0
        counts = {}
        for lab in labs:
            counts[lab] = counts.get(lab, 0) + 1
        return 1.0 - sum((c / n) ** 2 for c in counts.values())
    best_t, best_g = xs[0], float('inf')
    for t in sorted(set(xs)):
        left = [lab for x, lab in zip(xs, labels) if x < t]
        right = [lab for x, lab in zip(xs, labels) if x >= t]
        if not left or not right:
            continue
        g = (len(left) * _gini(left) + len(right) * _gini(right)) / len(labels)
        if g < best_g:
            best_g, best_t = g, t
    return best_t

